import json
import os

P = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'dist', 'content.json')
d = json.load(open(P, encoding='utf-8'))
E = {x['id']: x for x in d['entries']}
C = {c['id']: c for c in d['civilizations']}
S = {s['id'] for s in d['sources']}
ACC = '2026-10-19'


def src(i, title, url, kind='موسوعة مرجعية'):
    if i in S:
        return
    d['sources'].append({'id': i, 'title': title, 'url': url, 'accessed': ACC, 'type': kind,
                         'verification': 'روجعت الصفحة في 19 أكتوبر 2026؛ لا يعني ذلك تدقيقًا أكاديميًا شاملًا'})
    S.add(i)


